contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();
        require(c.currentBetLimit() == amount);
        uint256 balBefore = address(c).balance;
        bool firstOk = true;
        c.wager{value: amount}();
        bool wageredAfterFirst = c.hasPlayerWagered(address(this));
        uint256 balAfterFirst = address(c).balance;
        bool secondReverted;
        try c.wager{value: amount}() { secondReverted = false; }
        catch { secondReverted = true; }
        assert(
            firstOk &&
            wageredAfterFirst &&
            balAfterFirst == balBefore + amount &&
            secondReverted &&
            c.hasPlayerWagered(address(this)) &&
            address(c).balance == balAfterFirst
        );
    }
    receive() external payable {}
}

