contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 x, uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.OpenToThePublic();
        c.AdjustBetAmounts(x);
        bool recordedBefore = c.hasPlayerWagered(address(this));
        uint256 balanceBefore = c.ethBalance();
        bool wagerReverted;
        if (amount == x) {
            c.wager{value: amount}();
            wagerReverted = false;
        } else {
            try c.wager{value: amount}() { wagerReverted = false; } catch { wagerReverted = true; }
        }
        if (amount == x) {
            assert(!recordedBefore && c.hasPlayerWagered(address(this)) && c.ethBalance() == balanceBefore + amount && !wagerReverted);
        } else {
            assert(wagerReverted && !c.hasPlayerWagered(address(this)) && c.ethBalance() == balanceBefore);
        }
    }
    receive() external payable {}
}

